import React from 'react';
import { BrowserRouter, Routes, Route, Link } from 'react-router-dom';
import Dashboard from './pages/Dashboard';
import AlertsPage from './pages/AlertsPage';
import RawDataPage from './pages/RawDataPage';
import './App.css';

// This is the main part of the website
function App() {
  return (
    <BrowserRouter>
      <div className="whole-page-container">

        {/* The sidebar on the left */}
        <div className="left-sidebar">
          <div className="top-part">
            <span style={{fontSize: '30px'}}>📡</span>
            <h1 className="my-title">IoT Dashboard</h1>
          </div>

          <div className="menu-links">
            {/* I'm using regular Links and simple divs for the menu */}
            <div className="menu-item">
              <Link to="/" className="my-nav-link">
                <span>🏠</span> Dashboard
              </Link>
            </div>

            <div className="menu-item">
              <Link to="/alerts" className="my-nav-link">
                <span>🚨</span> Alerts
              </Link>
            </div>

            <div className="menu-item">
              <Link to="/raw-data" className="my-nav-link">
                <span>📊</span> Raw Data
              </Link>
            </div>
          </div>

          <div className="bottom-part">
            <p>IoT Monitor v1.0</p>
          </div>
        </div>

        {/* The main part where the pages change */}
        <div className="right-content-area">
          <Routes>
            <Route path="/" element={<Dashboard />} />
            <Route path="/alerts" element={<AlertsPage />} />
            <Route path="/raw-data" element={<RawDataPage />} />
          </Routes>
        </div>

      </div>
    </BrowserRouter>
  );
}

export default App;
